const fs = await import("node:fs").catch(() => null);
// fs not available in Code Mode; read files via tools instead
return "no-fs";

const model = `person "Customer" {
    "Places and tracks orders"
}

system "Order Platform" {
    "Accepts orders and manages fulfilment"
}

system "Payment Gateway" {
    "External payment processing"
}

container "Web Store" "order-web" "Web" {
    "Browser-based storefront"
}

container "Order API" "order-api" "Service" {
    "REST API for order management"
}

container "Order Database" "order-db" "PostgreSQL" {
    "Stores order data"
}

"Customer" -> "Web Store" "Shops and checks order status"
"Web Store" -> "Order API" "Submits orders" "HTTPS/JSON"
"Order API" -> "Order Database" "Persists orders" "SQL"
"Order API" -> "Payment Gateway" "Charges cards" "HTTPS/JSON"`;

const views = `systemContext "Order Platform" "order-platform-context" {
    "Shows how the Customer interacts with the Order Platform"
    include *
    autoLayout
}

container "Order Platform" "order-platform-containers" {
    "Shows the containers that make up the Order Platform"
    include *
    autoLayout
}

theme default`;

const dsl = `workspace "Order Platform" {
    model {
${model}
    }
    views {
${views}
    }
    !docs docs/
}`;

const parse = await tools.structurizr.parse({ dsl });
return { parse };

